using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using EFT;
using UnityEngine;
namespace LocalSpt5Esp;
internal static partial class RaidCommands {
 static ActorScenePreset SceneOptions(ActorScenePreset prior,JsonElement o){ChatCommandOptions.Keys(o,ChatCommandOptions.SceneKeys);var p=prior with{Enabled=true};foreach(var f in o.EnumerateObject())p=f.Name switch{
  "pose"=>p with{Pose=Enum.TryParse<ScenePose>(ChatCommandOptions.String(o,f.Name),true,out var pose)&&Enum.IsDefined(pose)?pose:throw new ArgumentException("姿势无效。")},
  "yaw"=>p with{Yaw=(float)ChatCommandOptions.Number(o,f.Name,-360000,360000)},"pitch"=>p with{Pitch=(float)ChatCommandOptions.Number(o,f.Name,-89,89)},
  "setFacing"=>p with{SetFacing=ChatCommandOptions.Bool(o,f.Name)},"noDoors"=>p with{NoDoors=ChatCommandOptions.Bool(o,f.Name)},"noHealing"=>p with{NoHealing=ChatCommandOptions.Bool(o,f.Name)},"noMovement"=>p with{NoMovement=ChatCommandOptions.Bool(o,f.Name)},
  "followDistance"=>p with{FollowDistance=(float)ChatCommandOptions.Number(o,f.Name,1,30)},"speed"=>p with{Speed=(float)ChatCommandOptions.Number(o,f.Name,.1,5)},
  "look"=>p with{Actions=ChatCommandOptions.Bool(o,f.Name)?p.Actions|SceneActions.LookAtPlayer:p.Actions&~SceneActions.LookAtPlayer},"follow"=>p with{Actions=ChatCommandOptions.Bool(o,f.Name)?p.Actions|SceneActions.FollowPlayer:p.Actions&~SceneActions.FollowPlayer},_=>p};return DirectorRules.Validate(p);}
 static Dictionary<string,BodyHealthPreset> HealthOptions(JsonElement o){if(o.ValueKind!=JsonValueKind.Object)throw new ArgumentException("bodyHealth 需要部位对象。");var result=new Dictionary<string,BodyHealthPreset>();foreach(var p in o.EnumerateObject()){ChatCommandOptions.Keys(p.Value,"maximum","current");float max=(float)ChatCommandOptions.Number(p.Value,"maximum",.01,float.MaxValue/8);float current=p.Value.TryGetProperty("current",out _)?(float)ChatCommandOptions.Number(p.Value,"current",0,max):max;if(!result.TryAdd(p.Name,new(max,current)))throw new ArgumentException("重复身体部位。");}AiBodyHealth.Validate(result);return result;}
 static SceneEffectPreset[] EffectsOptions(JsonElement o){if(o.ValueKind!=JsonValueKind.Array||o.GetArrayLength()>32)throw new ArgumentException("effects 最多32项。");return o.EnumerateArray().Select(e=>{ChatCommandOptions.Keys(e,"type","part","seconds","strength");string type=ChatCommandOptions.String(e,"type");if(!BuffRules.Common.Any(b=>b.Type==type))throw new ArgumentException("未知效果："+type);var part=e.TryGetProperty("part",out _)?Body(ChatCommandOptions.String(e,"part")):EBodyPart.Chest;if(type=="Fracture"&&part is not(EBodyPart.LeftArm or EBodyPart.RightArm or EBodyPart.LeftLeg or EBodyPart.RightLeg))throw new ArgumentException("骨折只支持四肢。");return new SceneEffectPreset(type,part.ToString(),e.TryGetProperty("seconds",out _)?(float)ChatCommandOptions.Number(e,"seconds",1,86400):30,e.TryGetProperty("strength",out _)?(float)ChatCommandOptions.Number(e,"strength",.01,1000000):1);}).ToArray();}
 static AiBirthPreset BirthOptions(AiBirthPreset prior,JsonElement o){ChatCommandOptions.Keys(o,ChatCommandOptions.ActorKeys);var p=prior;foreach(var f in o.EnumerateObject())p=f.Name switch{
  "name"=>p with{Name=ChatCommandOptions.String(o,f.Name,64)},"totalHealth"=>p with{Total=(float)ChatCommandOptions.Number(o,f.Name,0,float.MaxValue/8)},"healthPercent"=>p with{Percent=(float)ChatCommandOptions.Number(o,f.Name,.01,100)},
  "paused"=>p with{Paused=ChatCommandOptions.Bool(o,f.Name)},"invincible"=>p with{Invincible=ChatCommandOptions.Bool(o,f.Name)},"cleanEffects"=>p with{Clean=ChatCommandOptions.Bool(o,f.Name)},
  "playerRelation"=>p with{PlayerRelation=(int)ChatCommandOptions.Number(o,f.Name,0,2,true)},"aiRelation"=>p with{AiRelation=(int)ChatCommandOptions.Number(o,f.Name,0,2,true)},
  "bodyHealth"=>p with{BodyHealth=HealthOptions(f.Value)},"effects"=>p with{Effects=EffectsOptions(f.Value)},"scene"=>p with{Scene=SceneOptions(prior.Scene??new(){SetFacing=false},f.Value)},
  _=>p};return p;}
 static void SummonSpecified(GameWorld w,string[] a,JsonElement o){Vector3 point=a.Length>=4?Coordinates(w,a[1..4]):w.MainPlayer.Position+w.MainPlayer.Transform.forward*3;int count=a.Length>4?Integer(a[4],1,32):1,difficulty=a.Length>5?Integer(a[5],0,3):1;var basis=new AiBirthPreset(0,100,false,false,false,0,0,Array.Empty<string>(),EBodyPart.Chest,30,1);
  if(a[0].StartsWith("template:",StringComparison.OrdinalIgnoreCase)){var template=SceneTemplates.ChatTemplate(a[0][9..]);SceneTemplates.Spawn(w,point,template with{Count=count,Difficulty=difficulty,Birth=BirthOptions(template.Birth,o)});}else{string role=a[0].ToLowerInvariant() switch{"scav"=>"assault","usec"=>"pmcUSEC","bear"=>"pmcBEAR","raider"=>"pmcBot","rogue"=>"exUsec",_=>a[0]};var option=AiSpawnCatalog.Options.FirstOrDefault(v=>v.Role.Equals(role,StringComparison.OrdinalIgnoreCase)&&v.Enabled)??throw new ArgumentException("AI角色不存在或不可用。");AiSpawnService.Enqueue(w,point,option,difficulty,count,BirthOptions(basis,o),"详细聊天命令");}RaidChat.Output("已按详细出生参数排队；等待原生初始化。");
 }
 static void ConfigureActors(GameWorld w,string selector,JsonElement o){var targets=Ai(w,selector);var basis=new AiBirthPreset(0,100,false,false,false,0,0,Array.Empty<string>(),EBodyPart.Chest,30,1);var requested=BirthOptions(basis,o);
  var plans=targets.Select(p=>{var body=AiBodyHealth.Capture(p);if(o.TryGetProperty("totalHealth",out _)){float total=requested.Total;if(total<=0)throw new ArgumentException("现有AI总血量须大于0。");double sum=body.Values.Sum(v=>(double)v.Maximum);body=body.ToDictionary(v=>v.Key,v=>new BodyHealthPreset((float)(total*v.Value.Maximum/sum),(float)(total*v.Value.Current/sum)));}if(o.TryGetProperty("healthPercent",out _))body=body.ToDictionary(v=>v.Key,v=>v.Value with{Current=v.Value.Maximum*requested.Percent/100});if(requested.BodyHealth!=null)foreach(var v in requested.BodyHealth)body[v.Key]=v.Value;AiBodyHealth.Validate(body);var scene=o.TryGetProperty("scene",out var s)?SceneOptions(AiSceneDirector.For(p),s):null;return(Player:p,Body:body,Scene:scene);}).ToArray();
  foreach(var plan in plans){var p=plan.Player;if(o.TryGetProperty("name",out _))p.Profile.Info.Nickname=requested.Name;if(o.TryGetProperty("totalHealth",out _)||o.TryGetProperty("healthPercent",out _)||o.TryGetProperty("bodyHealth",out _))AiBodyHealth.Apply(p,plan.Body);if(o.TryGetProperty("invincible",out _)){var state=AiActorControl.EditorState(p);AiActorControl.ApplyEditorState(w,p,requested.Invincible,state.Damage);}if(o.TryGetProperty("playerRelation",out _)||o.TryGetProperty("aiRelation",out _))AiActorControl.CommandRelations(w,p,o.TryGetProperty("playerRelation",out _)?requested.PlayerRelation:null,o.TryGetProperty("aiRelation",out _)?requested.AiRelation:null);if(requested.Clean)CharacterBuffs.ClearBirthEffects(p);if(requested.Effects!=null)foreach(var e in requested.Effects)CharacterBuffs.AddBirthBuff(w,p,e.Type,Body(e.Part),e.Seconds,e.Strength);if(plan.Scene!=null)AiSceneDirector.Apply(w,p,plan.Scene);if(o.TryGetProperty("paused",out _))AiTestControl.SetPaused(new[]{p},requested.Paused);}RaidChat.Output("已按详细参数配置 "+plans.Length+" 个AI。");
 }
}
